contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, bool asOwner) public {
        address before = c.owner();
        bool reverted;
        if (asOwner && before == address(this)) {
            bool ok = c.setOwner(newOwner);
            assert(ok && c.owner() == newOwner);
        } else {
            try c.setOwner(newOwner) { reverted = false; } catch { reverted = true; }
            assert(reverted && c.owner() == before);
        }
    }
    receive() external payable {}
}

